function getVideoResolution(level) {
    let { width, height, bitrate, frameRate } = {
        width: 640,
        height: 360,
        bitrate: 400,
        frameRate: 15,
    };
    if (level === "180p") {
        width = 320;
        height = 180;
        bitrate = 140;
    }
    else if (level === "360p") {
        width = 640;
        height = 360;
        bitrate = 400;
    }
    else if (level === "480p") {
        width = 640;
        height = 480;
        bitrate = 500;
    }
    else if (level === "540p") {
        width = 960;
        height = 540;
        bitrate = 800;
    }
    else if (level === "720p") {
        width = 1280;
        height = 720;
        bitrate = 1130;
    }
    else if (level === "1080p") {
        width = 1920;
        height = 1080;
        bitrate = 1500;
    }
    return {
        width,
        height,
        bitrate,
        frameRate,
    };
}
